    image_patch = ImagePatch(image)
    apples = image_patch.find("apple")
    bowls = image_patch.find("bowl")

    if not apples or not bowls:
        return image_patch

    apple_patches = []
    for apple in apples:
        for bowl in bowls:
            if apple.overlaps_with(bowl.left, bowl.lower, bowl.right, bowl.upper):
                apple_patches.append(apple)
                break

    if not apple_patches:
        return image_patch

    apple_patches.sort(key=lambda p: p.vertical_center)
    return apple_patches[0]

